/// <summary>
/// The <c>AVAWHSWorkUserSessionDbt_Extension</c> represents a extension of WHSWorkUserSession.
/// </summary>
[
    ExtensionOf(tableStr(WHSWorkUserSession))
]
final class AVAWHSWorkUserSessionDbt_Extension
{
}

Method.Source:
/// <summary> 
/// update printer for user
/// </summary> 
/// <param name = "_userId">user id</param> 
/// <param name = "_printerCode">printer code</param> 
public static void avaUpdatePrinter(WHSUserId _userId, AVAPrinterCode _printerCode)
{ 
    WHSWorkUserSession userSession; 

    if (_userId && _printerCode)
    { 
        ttsbegin;

        userSession = WHSWorkUserSession::find(_userId, true);

        if (userSession)
        {
            userSession.AVAPrinterCode = _printerCode;
            userSession.update();
        }

        ttscommit;
    }
}
